aydate=result['holiday_date'];								$("#eid").val(uid);				$("#dpr").val(dpr);				$("#holiday").val(holidayname);				$(".holidaydate").val(holidaydate);							 }			});									$("#submit").html('Update');		    });    $("#reset").click(function(){					$("#eid").val('');			$("#submit").html('Add');		    });});</script>    </section>    <!-- /.content -->  </div>      <!-- /.content-wrapper -->  <footer class="main-footer">        <strong>Copyright &copy; 2018 <a href="#">Fddi</a>.</strong> All rights    reserved.  </footer>   <!-- /.control-sidebar -->  <!-- Add the sidebar's background. This div must be placed       immediately after the control sidebar -->  <div class="control-sidebar-bg"></div></div><!-- ./wrapper --></body></html>